def parse_port(spec):
    """ports 条目解析成 (宿主IP, 宿主端口, 容器端口, 协议)。

    支持三种写法：
      "8080"        -> 只发布容器端口，宿主端口随机
      "8080:80"     -> 宿主 8080 -> 容器 80
      "127.0.0.1:8080:80" -> 绑定指定宿主 IP
    """
    parts = str(spec).split(":")
    proto = "tcp"
    if "/" in parts[-1]:
        tail = parts[-1].split("/")
        parts[-1] = tail[0]
        proto = tail[1]
    if len(parts) == 1:
        return ("0.0.0.0", None, int(parts[0]), proto)
    if len(parts) == 2:
        return ("0.0.0.0", int(parts[0]), int(parts[1]), proto)
    return (parts[0], int(parts[1]), int(parts[2]), proto)


def detect(services):
    used = {}
    conflicts = []
    exposed_only = []
    for name, spec in services.items():
        for p in spec.get("ports") or []:
            ip, host, cont, proto = parse_port(p)
            if host is None:
                exposed_only.append((name, cont))
                continue
            key = (ip, host, proto)
            if key in used:
                conflicts.append((used[key], name, ip, host, proto))
            else:
                used[key] = name
    return conflicts, exposed_only, used


def show(title, services):
    print("=== %s ===" % title)
    for name, spec in services.items():
        print("  %-8s ports=%s" % (name, spec.get("ports") or []))
    conflicts, exposed_only, used = detect(services)
    print("  已占用的宿主端口: %s" % sorted((h, n) for (ip, h, p), n in used.items()))
    print("  仅声明容器端口（宿主端口随机，不构成冲突）: %s" % (exposed_only or "无"))
    print("  冲突数 = %d" % len(conflicts))
    for a, b, ip, h, proto in conflicts:
        print("  冲突: %s:%d/%s 被 %s 与 %s 同时声明" % (ip, h, proto, a, b))
    print("  判定：可以 up = %s" % (not conflicts))
    print()
    return bool(conflicts)


